"""Complete 40 original poisoning and antidote questions."""
from create_critical_toxic_alcohols import rows,q,AH,IC,AC,AP,NA,SA,ME,EG,LI,CO,ref
from qbank_authoring import finalize

q('Three days after apparent improvement from organophosphate poisoning, a patient develops neck-flexor, proximal-limb and respiratory weakness with relatively few secretions. Which syndrome is most likely?', 'Organophosphate intermediate syndrome',[
 ('Recurrent muscarinic crisis as established by weakness alone','Recurrent crisis is supported by renewed secretory/autonomic findings; weakness alone is not sufficient.'),('Delayed distal axonal neuropathy beginning several weeks later','That has a later time course and different distribution.'),('Pure atropine toxicity','That produces an antimuscarinic syndrome rather than this characteristic neuromuscular pattern.')],
 'Respiratory risk persists after the wet phase improves','**Intermediate syndrome can emerge after the initial cholinergic crisis.**',['Proximal, neck, cranial and respiratory muscles can be affected.','An apparently dry chest does not establish safe neuromuscular function.'],'**Monitor strength and ventilation and provide respiratory support when needed.**',['Differentiate recurrent poisoning, electrolyte deficits and other ICU weakness.','Do not use further atropine as a substitute for ventilatory support of nicotinic weakness.'],[['Timing','Often 1–4 days'],['Distribution','Proximal/neck/respiratory'],['Main need','Close respiratory assessment']],[IC],style='clinical_scenario')

q('What does aging of an organophosphate–acetylcholinesterase complex mean for oxime treatment?', 'Chemical stabilization of the inhibited enzyme makes oxime reactivation ineffective after aging',[
 ('The patient has become too old to receive atropine','Aging refers to the enzyme–toxin complex, not patient age.'),('Atropine becomes unable to block muscarinic receptors','Atropine antagonism does not require enzyme reactivation.'),('Every organophosphate has the same fixed reactivation window','Aging rates vary substantially between compounds.')],
 'Different antidotes act at different sites','**Oximes attempt to reactivate inhibited acetylcholinesterase before the complex ages.**',['Timing and compound influence potential benefit.','Clinical oxime efficacy is not identical across all pesticide exposures.'],'**Do not delay atropine and airway support while determining the exact compound.**',['Use a toxicology-guided oxime regimen when indicated.','Cholinesterase assays are supportive rather than a reason to defer resuscitation.'],[['Atropine','Receptor antagonism'],['Oxime','Enzyme reactivation'],['Aging','Reduced/absent reactivatability']],[IC])

q('After ingesting a grain fumigant tablet, a patient develops profound myocardial dysfunction, shock and severe acidosis. Aluminium phosphide is suspected. Which statement is correct?', 'Phosphine-mediated toxicity requires intensive supportive care; there is no established specific antidote',[
 ('Atropine is a specific antidote because all pesticides inhibit cholinesterase','Phosphide toxicity is distinct from the organophosphate cholinergic syndrome.'),('Pralidoxime reliably reverses the myocardial toxin','It reactivates selected inhibited cholinesterase, not phosphine injury.'),('A normal early blood pressure excludes subsequent severe toxicity','Cardiovascular deterioration can be rapid and profound.')],
 'Pesticide labels do not imply a shared toxic mechanism','**Moisture liberates phosphine from metal phosphides.**',['Cellular and myocardial injury can cause refractory shock.','Secondary exposure to released gas is a staff-safety concern.'],'**Use protected handling and early ICU/toxicology support.**',['Follow perfusion, ECG, acid-base status and organ injury.','Consider advanced support in selected refractory cases at an experienced center.'],[['Agent','Aluminium phosphide'],['Toxic gas','Phosphine'],['Treatment','Supportive; no established specific antidote']],[IC],style='clinical_scenario')

q('Which delayed complication is particularly characteristic of surviving paraquat poisoning?', 'Progressive pulmonary fibrosis',[
 ('A predictable cholinergic intermediate syndrome','That follows selected organophosphate exposures.'),('Delayed calcium oxalate nephropathy as the defining mechanism','This is characteristic of ethylene glycol metabolism.'),('Isolated reversible opioid respiratory depression','Paraquat is not an opioid receptor agonist.')],
 'Paraquat can cause progressive organ injury after initial exposure','**Pulmonary uptake and oxidative injury can lead to fibrosis.**',['Renal, hepatic and mucosal injury may also occur.','No proven specific antidote reliably reverses the syndrome.'],'**Seek early toxicology guidance and provide carefully targeted support.**',['Avoid unnecessary hyperoxia, while treating clinically important hypoxemia.','Discuss prognosis and treatment limitations using the exposure and evolving clinical evidence.'],[['Early','GI/mucosal and systemic injury'],['Later','Pulmonary fibrosis'],['Antidote','No proven specific agent']],[ref('ISCCM paraquat poisoning position statement: 2026','https://pmc.ncbi.nlm.nih.gov/articles/PMC13585111/')])

q('A patient with severe iron overdose has shock, acidosis and systemic toxicity. Which chelator is appropriate?', 'Deferoxamine',[
 ('Calcium disodium EDTA','This is used for selected lead poisoning, not the standard iron antidote.'),('Digoxin-specific Fab','These antibody fragments bind cardiac glycosides.'),('Fomepizole','This blocks toxic-alcohol metabolism rather than chelating iron.')],
 'Iron toxicity requires an iron-directed chelator','**Free iron impairs cellular processes and can cause severe GI and systemic injury.**',['A transient period of apparent improvement can precede organ failure.','Serum concentration must be interpreted with timing and clinical toxicity.'],'**Resuscitate and use specialist-guided deferoxamine for severe systemic poisoning.**',['Activated charcoal does not reliably adsorb iron.','Evaluate retained tablets and decontamination options when appropriate.'],[['Toxin','Iron'],['Chelator','Deferoxamine'],['Warning','Shock/acidosis or severe systemic manifestations']],[IC],style='clinical_scenario')

q('Which chelation approach is appropriate for severe lead poisoning with encephalopathy under specialist management?', 'A parenteral regimen using calcium disodium EDTA with appropriate dimercaprol coverage',[
 ('Disodium EDTA substituted freely for calcium disodium EDTA','Disodium EDTA can cause fatal hypocalcemia; the salts are not interchangeable.'),('Oral succimer alone as the routine choice despite severe encephalopathy','Severe CNS toxicity requires an appropriate intensive parenteral approach.'),('Deferoxamine as the lead-specific first-line chelator','It is the standard iron chelator rather than the preferred lead regimen.')],
 'Specify the chelator and salt precisely','**Severe neurological lead toxicity is a medical emergency.**',['The regimen must account for redistribution and kidney monitoring.','Removal from exposure remains essential even when chelation is used.'],'**Coordinate toxicology, intensive care and exposure control.**',['Monitor renal function and the blood lead trajectory.','Do not confuse calcium disodium EDTA with disodium EDTA.'],[['Severe CNS toxicity','Specialist parenteral chelation'],['CaNa2EDTA','Correct calcium-containing salt'],['Na2EDTA','Dangerous substitution']],[ref('WHO guideline: clinical management of lead exposure','https://www.ncbi.nlm.nih.gov/books/NBK575289/')])

q('An adult develops refractory seizures, coma and severe acidosis after an isoniazid overdose. Which antidote directly addresses the characteristic neurotransmitter deficit?', 'Intravenous pyridoxine',[
 ('Flumazenil','It can worsen seizures and does not restore the impaired cofactor pathway.'),('Naloxone','It antagonizes opioid receptors rather than treating isoniazid-related GABA depletion.'),('Folinic acid','It has roles in other toxic exposures but does not replace the relevant pyridoxine pathway.')],
 'Isoniazid can impair GABA synthesis','**Functional pyridoxal-phosphate depletion compromises inhibitory neurotransmission.**',['Seizures can be difficult to control with usual anticonvulsants alone.','Dose selection depends on the known ingestion or the recommended empirical protocol.'],'**Give pyridoxine with benzodiazepines and airway/metabolic support.**',['Do not delay antidote procurement in a compatible severe presentation.','Control prolonged muscle activity and monitor temperature and rhabdomyolysis.'],[['Toxin','Isoniazid'],['Deficit','Pyridoxine-related GABA synthesis'],['Antidote','Pyridoxine']],[ref('South African adult hospital poisoning treatment guideline: 2025','https://www.health.gov.za/wp-content/uploads/2025/04/Adult-Hospital-Chapter-19-Poisoning-with-supporting-NEMLC-report-2020-4-Version-2.0-27-March-2025.pdf')],style='clinical_scenario')

q('A sulfonylurea overdose causes recurrent hypoglycemia after initial IV glucose correction. Which adjunct most directly limits further drug-driven insulin secretion?', 'Octreotide',[
 ('Repeated glucose alone as the only strategy despite recurrent episodes','Glucose can stimulate further insulin release in this context.'),('High-dose insulin','This is used in selected cardiotoxic overdoses and would worsen hypoglycemia here.'),('Fomepizole','Alcohol dehydrogenase inhibition does not suppress sulfonylurea-driven insulin release.')],
 'Break the recurrent glucose–insulin cycle','**Octreotide suppresses pancreatic insulin secretion.**',['Correct immediate neuroglycopenia with glucose first.','Long-acting formulations can produce prolonged recurrence.'],'**Monitor after treatment and after stopping the antidote.**',['Provide nutrition when safe and assess coingestants.','Observation duration depends on the agent and clinical course.'],[['Immediate rescue','Glucose'],['Recurrent secretory driver','Sulfonylurea-induced insulin'],['Adjunct','Octreotide']],[ref('Queensland Poisons Information Centre: octreotide','https://www.poisonsinfo.health.qld.gov.au/for-health-professionals/antidote-stocking-recommendations/octreotide')],style='clinical_scenario')

q('A metformin-exposed patient with AKI has lactate 24 mmol/L, pH 6.95 and persistent shock. Which escalation is supported?', 'Urgent extracorporeal treatment, usually bicarbonate-buffered intermittent hemodialysis when feasible',[
 ('Wait for a metformin concentration before considering dialysis','Severe clinical and acid-base criteria justify action without a delayed drug assay.'),('Treat with oral activated charcoal as the sole intervention','This cannot correct established severe systemic acidosis and shock.'),('Assume the lactate must be benign because the glucose is normal','Metformin-associated toxicity is not excluded by normal glucose.')],
 'Severe lactate and acidemia identify a high-risk poisoning syndrome','**EXTRIP supports extracorporeal treatment for severe metformin poisoning.**',['Shock and kidney impairment lower the threshold for escalation.','Sepsis, ischemia and other lactate causes can coexist and need treatment.'],'**Resuscitate while arranging toxin removal and acid-base support.**',['Monitor for recurrence and use the recommended recovery endpoints.','Select a continuous alternative when intermittent treatment is unavailable or unsuitable.'],[['Lactate','24 mmol/L'],['pH','6.95'],['Escalation','Urgent extracorporeal support']],[ref('EXTRIP metformin recommendations','https://www.extrip-workgroup.org/metformin')],style='clinical_scenario')

q('Soon after a local-anesthetic injection, a patient develops seizures followed by cardiovascular instability. Which specific rescue therapy should be included for severe local-anesthetic systemic toxicity?', 'Intravenous 20% lipid emulsion according to a LAST protocol',[
 ('Propofol substituted as an equivalent lipid dose','Propofol is not an interchangeable lipid-rescue formulation and can worsen cardiovascular depression.'),('Large routine vasopressin doses as the preferred LAST-specific drug','LAST resuscitation has important departures from ordinary arrest drug choices.'),('Additional local anesthetic to suppress all ventricular ectopy','This can aggravate the toxic mechanism.')],
 'Recognize a procedure-related toxic emergency','**Local-anesthetic systemic toxicity can cause both CNS and cardiovascular collapse.**',['Stop further local anesthetic and call for help.','Oxygenation, ventilation and seizure control reduce aggravating hypoxia/acidosis.'],'**Use the current LAST checklist with lipid rescue and modified resuscitation choices.**',['Avoid indiscriminate large catecholamine doses and other contraindicated agents.','Arrange ongoing observation and advanced support for refractory collapse.'],[['Exposure','Local anesthetic'],['CNS','Seizures may precede collapse'],['Specific rescue','20% lipid emulsion']],[ref('ASRA LAST treatment checklist','https://asra.com/news-publications/asra-updates/blog-landing/guidelines/2020/11/01/checklist-for-treatment-of-local-anesthetic-systemic-toxicity')],style='clinical_scenario')

if __name__=='__main__':finalize('Critical Care and Toxicology',5,'Common Poisonings and Antidotes','critical-poisoning',rows,40)
